<script lang="ts">
import { defineComponent } from "vue";import { useAdmConsolePage } from "../../app/useAdmConsolePage";import CpfIcon from "../../components/CpfIcon.vue";
export default defineComponent({setup(){return useAdmConsolePage()},name:"TopologyPage",components:{CpfIcon},computed:{services(){return this.serviceRegistryResult?.services||[]},instances(){return this.serviceRegistryResult?.instances||[]},health(){return this.serviceRegistryResult?.health||[]},nodes(){return this.services.map((s:any)=>({service:s,instances:this.instances.filter((i:any)=>i.serviceId===s.serviceId)}))}}});
</script><template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">SERVICE TOPOLOGY</p><h2>서비스 토폴로지</h2><p>서비스·Endpoint·Instance와 Health 상태를 운영 관점으로 시각화합니다.</p></div><button class="ghost" @click="loadServiceRegistry"><CpfIcon name="refresh"/> 새로고침</button></div><section class="cpf-topology"><article v-for="node in nodes" :key="String(node.service.serviceId)" class="cpf-node"><div class="cpf-node-title"><div><p class="eyebrow">SERVICE</p><h3>{{node.service.serviceId}}</h3></div><span class="cpf-status info">{{node.instances.length}} instances</span></div><p class="meta">{{node.service.serviceName||node.service.description||'CPF service'}}</p><div v-for="i in node.instances" :key="String(i.instanceId)" class="instance-row"><div><strong>{{i.instanceName||i.instanceId}}</strong><small>{{i.endpointCode}} · weight {{i.weight??'-'}}</small></div><span class="cpf-status" :class="['UP','ACTIVE','READY'].includes(String(i.instanceStatus||'').toUpperCase())?'success':'danger'">{{i.instanceStatus}}</span></div></article><div v-if="!nodes.length" class="cpf-card cpf-empty">Service Registry 데이터가 없습니다.</div></section></div></template>